#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1050;
int Mod;
int add(int a, int b) { return a + b >= Mod ? a + b - Mod : a + b; }
int dec(int a, int b) { return a - b < 0 ? a - b + Mod : a - b; }
int mul(int a, int b) { return (long long)a * b % Mod; }
void Add(int &a, int b) { a = add(a, b); }
void Dec(int &a, int b) { a = dec(a, b); }
void Mul(int &a, int b) { a = mul(a, b); }

int C[MAXN][MAXN];
int f[MAXN], g[MAXN];
int n, m;

void compute_combinations(int n) {
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = add(C[i - 1][j - 1], C[i - 1][j]);
    }
}

int main() {
    cin >> n >> m >> Mod;
    f[1] = 2; g[1] = 0;
    int limit = max(m, n - m + 1);
    compute_combinations(limit);
    for (int i = 2; i <= m; ++i) {
        f[i] = mul(f[i - 1], 2 * (i + 1));
        g[i] = mul(g[i - 1], 2 * (i + 1));
        Add(g[i], mul(f[i - 1], i * (i - 1)));
        for (int j = 1; j < i; ++j) {
            int k = i - j - 1;
            int c = mul(C[j + k][j], j + k + 2);
            Add(f[i], mul(c, mul(f[j], f[k])));
            Add(g[i], mul(c, mul(f[j], g[k])));
            Add(g[i], mul(c, mul(g[j], f[k])));
            int w = j * (j + 1) / 2 + k * (k + 1) / 2;
            Add(g[i], mul(mul(C[j + k][j], w), mul(f[j], f[k])));
        }
    }
    static int dp[MAXN][MAXN][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= m; ++j)
            for (int o = 0; o < 2; ++o) {
                int c = dp[i][j][o];
                if (c != 0) {
                    if (o == 0) {
                        for (int k = 1; k + j <= m; ++k) {
                            Add(dp[i + 1][j + k][0], mul(mul(c, C[j + k][k]), f[k]));
                            Add(dp[i + 1][j + k][1], mul(mul(c, C[j + k][k]), g[k]));
                        }
                    } else {
                        for (int k = 1; k + j <= m; ++k) {
                            Add(dp[i + 1][j + k][1], mul(mul(c, C[j + k][k]), f[k]));
                        }
                    }
                }
            }
    int ans = 0;
    for (int i = 1; i <= m; ++i)
        Add(ans, mul(dp[i][m][1], C[n - m + 1][i]));
    cout << ans;
    return 0;
}
